(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const mx = x + w1x, my = y + w1y;
  const w2x = Math.sin(mx*0.015+my*0.01+t*0.5)*8 + Math.cos(my*0.02-t*0.4)*6;
  const w2y = Math.cos(mx*0.018-my*0.012-t*0.45)*8 + Math.sin(mx*0.01+t*0.55)*6;
  const sx = mx + w2x, sy = my + w2y;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1],
    [400+Math.cos(t*0.38+6)*60, 200+Math.sin(t*0.72+4)*55, 0.085, 1.8]
  ];
  let aS = 0, iS = 0, tS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    aS += Math.sin(d*f - t*sp);
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5);
    tS += Math.sin(d*f*0.5 - t*sp*0.4 + 3.0) * 0.5;
  }
  const act = aS/8, inh = iS/8, ter = tS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2 + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2 + Math.sin(sx*0.08+sy*0.06-t*1.5)*0.15 + Math.sin(sx*0.02+sy*0.03+t*0.4)*0.3;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5) + Math.sin(dist*0.04+ang*4-t*1.2))*0.4 + Math.sin(dist*0.03-ang*6+t*0.8)*0.2;
  const rd1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const rd2 = Math.tanh((ter - act*0.5 + inh*0.4 + spiral*0.5)*1.8);
  const rd3 = Math.tanh((inh - ter*0.6 - act*0.3 + bg*0.4)*1.6);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15) + Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const blend = rd1*0.5 + rd2*0.25 + cell*0.25;
  const mod = Math.tanh(rd3*2.5)*0.15;
  const v = Math.max(0, Math.min(1, blend*0.5+0.5+mod));
  const pal = [[5,12,45],[12,45,85],[20,90,120],[30,140,135],[120,175,100],[210,185,60],[230,140,50],[200,80,60],[150,45,55],[80,20,45],[30,10,35],[5,12,45]];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const energy = Math.abs(rd1) + Math.abs(rd2)*0.5;
  const lum = 0.75 + Math.sin(energy*Math.PI)*0.25;
  const edge = energy > 1.2 ? 1.2 : energy > 0.8 ? 1.05 : 1.0;
  const glow = Math.max(0, Math.sin(t*1.2+dist*0.02)*0.5+0.5)*0.08;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*lum*edge + glow*80)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*lum*edge + glow*100)|0)
  ];
}
